      MIPStarRE.QPBT.Measurement.IsProjective.{0, 0} (points.extendedQ side x z alpha beta)) ∧
    (∀ (p1 p2 : MIPStarRE.QPBT.Placement),
        p1.IsOpposite p2 →
          LE.le.{0}
            (MIPStarRE.QPBT.opFamilyDistSq.{0, 0, 0}
              (LIDT.MIPStarRE.LDT.uniformDistribution.{0} (MIPStarRE.QPBT.ExtendedPointQuestion P))
              (fun question c =>
                S.place p1
                  (LIDT.MIPStarRE.Quantum.Submeasurement.effect.{0, 0}
                    (LIDT.MIPStarRE.Quantum.Measurement.toSubmeasurement.{0, 0}
                      (points.extendedQ p1.side question.1.1 question.1.2 question.2.1 question.2.2))
                    c))
